import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2021-12-23","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-12-23","date":"2021-12-23T00:00:00.000Z","updated":"2021-12-24T00:00:00.000Z","tags":["Ceph","性能优化","BlueStore","内存管理","分布式存储"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-12-23.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-12-23.md","lastUpdated":1780460162000}'),t={name:"posts/2021/Ceph_Performance_Meeting_2021-12-23.md"};function o(n,l,s,u,p,h){return a(),r("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph性能会议主要讨论了系统中关键问题的改进措施，包括性能优化、代码重构、内存管理等多个方面。会议由Mark主持，参与人员包括Adam、Igor、Laura等。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Pinning逻辑的改进</strong>：</p><ul><li>Adam和Igor提出了针对BlueStore中pinning逻辑的改进方案，特别是针对O_NOCACHE的操作。</li><li>这些改进可能会影响性能，但有助于减少对tracker box的依赖，提高系统稳定性。</li></ul></li><li><p><strong>BlueStore日志的增量更新模式</strong>：</p><ul><li>Adam介绍了BlueStore日志的增量更新模式，该模式已通过测试，目前正在进一步的审查中。</li></ul></li><li><p><strong>TTL缓存实现和Primary Balancer PR</strong>：</p><ul><li>Laura和Joshua正在合作进行Primary Balancer PR的代码重构，目的是使代码更加模块化和易于维护。</li><li>该PR的目标是保持Balancer的功能不变，同时提高代码的可读性和可维护性。</li></ul></li><li><p><strong>内存使用和性能优化</strong>：</p><ul><li>讨论了BlueStore中内存使用问题，特别是关于blob fsck的内存消耗。</li><li>Igor提出了一个内存减少的PR，旨在优化BlueStore的内存使用，减少系统资源消耗。</li></ul></li><li><p><strong>EC2设备性能问题</strong>：</p><ul><li>讨论了在Amazon EC2上运行Ceph时遇到的一些性能问题，特别是关于IOPS保证和实际性能差异。</li><li>提出了可能的解决方案，包括增加IO合并和调整BlueStore的并发IO设置。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>Pinning逻辑的改进</strong>：</p><ul><li>同意继续推进Adam和Igor的改进方案，并进行进一步的测试和审查。</li></ul></li><li><p><strong>BlueStore日志的增量更新模式</strong>：</p><ul><li>确认该模式已通过测试，将继续进行代码审查和优化。</li></ul></li><li><p><strong>Primary Balancer PR</strong>：</p><ul><li>同意Laura和Joshua继续合作进行代码重构，并确保重构后的代码功能不变。</li></ul></li><li><p><strong>内存使用优化</strong>：</p><ul><li>同意Igor的内存减少PR，并计划在满足内存边界的前提下进行合并。</li></ul></li><li><p><strong>EC2性能问题</strong>：</p><ul><li>计划进一步研究和测试，以确定是否需要调整BlueStore的并发IO设置。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>Pinning逻辑的改进</strong>：</p><ul><li>继续进行代码审查和测试，确保改进方案的有效性。</li></ul></li><li><p><strong>BlueStore日志的增量更新模式</strong>：</p><ul><li>完成代码审查，并进行必要的优化。</li></ul></li><li><p><strong>Primary Balancer PR</strong>：</p><ul><li>继续进行代码重构，并确保重构后的代码功能不变。</li></ul></li><li><p><strong>内存使用优化</strong>：</p><ul><li>完成Igor的内存减少PR的审查，并进行合并。</li></ul></li><li><p><strong>EC2性能问题</strong>：</p><ul><li>进行进一步的测试和研究，以确定是否需要调整BlueStore的并发IO设置。</li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了Ceph在不同硬件配置下的性能表现，以及内存限制和硬件成本的权衡。</li><li>讨论了Ceph在不同环境下的部署策略，包括使用SSD和HDD的混合部署。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后结束，Mark祝愿大家新年快乐，并期待在新的一年中继续合作。</p><p>以上是本次会议的详细纪要，涵盖了会议的主要内容、讨论的议题、决定的事项以及后续的行动计划。希望这份纪要能帮助大家更好地理解和跟进会议的成果。</p>',14)])])}const c=e(t,[["render",o]]);export{d as __pageData,c as default};
